import PocketBase from 'pocketbase';

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

// Helper to calculate date strings
function getDateString(daysAgo = 0) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

async function setup() {
  console.log('Setting up PocketBase...');
  console.log('Backend URL:', BACKEND_URL);

  try {
    // Try to authenticate as admin - if no admin exists, we'll need to create one
    // For now, let's assume PocketBase is already set up with admin access
    // We'll create collections programmatically

    // Check if users collection exists (it should be built-in)
    let usersCollection;
    try {
      usersCollection = await pb.collections.getOne('users');
      console.log('✓ Users collection exists');
    } catch (e) {
      console.log('Creating users collection...');
      // Users collection should be built-in, if not we have a problem
      throw new Error('Users collection does not exist - PocketBase may not be properly initialized');
    }

    // Create or update habits collection
    try {
      const habitsCollection = await pb.collections.getOne('habits');
      console.log('✓ Habits collection already exists');
    } catch (e) {
      console.log('Creating habits collection...');
      await pb.collections.create({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: usersCollection.id,
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: {
              min: 1,
              max: 80,
              pattern: ''
            }
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: {
              min: null,
              max: 200,
              pattern: ''
            }
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest']
            }
          },
          {
            name: 'deleted',
            type: 'bool',
            required: false,
            options: {}
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_habits_user_name ON habits(user_id, LOWER(name)) WHERE deleted = FALSE'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = FALSE',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      });
      console.log('✓ Habits collection created');
    }

    // Create or update completions collection
    try {
      const completionsCollection = await pb.collections.getOne('completions');
      console.log('✓ Completions collection already exists');
    } catch (e) {
      console.log('Creating completions collection...');
      const habitsCollection = await pb.collections.getOne('habits');
      await pb.collections.create({
        name: 'completions',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: usersCollection.id,
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'habit_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: habitsCollection.id,
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'date',
            type: 'text',
            required: true,
            options: {
              min: null,
              max: null,
              pattern: '^\\d{4}-\\d{2}-\\d{2}$'
            }
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_completions_unique ON completions(user_id, habit_id, date)'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: null,
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      });
      console.log('✓ Completions collection created');
    }

    // Seed user
    console.log('Seeding data...');
    let demoUser;
    try {
      // Try to find existing user
      const users = await pb.collection('users').getFullList({
        filter: 'email = "demo@ethara.ai"'
      });
      if (users.length > 0) {
        demoUser = users[0];
        console.log('✓ Demo user already exists:', demoUser.id);
      } else {
        throw new Error('User not found');
      }
    } catch (e) {
      // Create demo user
      console.log('Creating demo user...');
      demoUser = await pb.collection('users').create({
        email: 'demo@ethara.ai',
        password: 'deku-demo-pw-2026',
        passwordConfirm: 'deku-demo-pw-2026',
        emailVisibility: true,
        verified: true
      });
      console.log('✓ Demo user created:', demoUser.id);
    }

    // Seed habits
    const habitNames = ['Meditate', 'Read 20 minutes', 'No soda'];
    const habitColors = ['indigo', 'teal', 'amber'];
    const habits = [];

    for (let i = 0; i < habitNames.length; i++) {
      try {
        // Check if habit already exists
        const existing = await pb.collection('habits').getFullList({
          filter: `user_id = "${demoUser.id}" && name = "${habitNames[i]}" && deleted = FALSE`
        });
        if (existing.length > 0) {
          habits.push(existing[0]);
          console.log(`✓ Habit "${habitNames[i]}" already exists`);
        } else {
          throw new Error('Habit not found');
        }
      } catch (e) {
        const habit = await pb.collection('habits').create({
          user_id: demoUser.id,
          name: habitNames[i],
          description: '',
          color: habitColors[i],
          deleted: false
        });
        habits.push(habit);
        console.log(`✓ Created habit: ${habitNames[i]}`);
      }
    }

    // Seed completions
    const today = getDateString(0);

    // Meditate: 5-day streak (today + 4 days before)
    for (let i = 0; i < 5; i++) {
      const date = getDateString(i);
      try {
        await pb.collection('completions').create({
          user_id: demoUser.id,
          habit_id: habits[0].id,
          date: date
        });
        console.log(`✓ Created completion for Meditate on ${date}`);
      } catch (e) {
        if (e.status === 400) {
          console.log(`  Completion for Meditate on ${date} already exists`);
        } else {
          console.error(`Error creating completion:`, e);
        }
      }
    }

    // Read 20 minutes: longest_streak of 3, current_streak of 0
    // Create 3-day streak somewhere in the past (7-9 days ago)
    for (let i = 7; i <= 9; i++) {
      const date = getDateString(i);
      try {
        await pb.collection('completions').create({
          user_id: demoUser.id,
          habit_id: habits[1].id,
          date: date
        });
        console.log(`✓ Created completion for Read 20 minutes on ${date}`);
      } catch (e) {
        if (e.status === 400) {
          console.log(`  Completion for Read 20 minutes on ${date} already exists`);
        } else {
          console.error(`Error creating completion:`, e);
        }
      }
    }

    // No soda: current_streak of 1 (only today)
    try {
      await pb.collection('completions').create({
        user_id: demoUser.id,
        habit_id: habits[2].id,
        date: today
      });
      console.log(`✓ Created completion for No soda on ${today}`);
    } catch (e) {
      if (e.status === 400) {
        console.log(`  Completion for No soda on ${today} already exists`);
      } else {
        console.error(`Error creating completion:`, e);
      }
    }

    console.log('\n✅ PocketBase setup complete!');
  } catch (error) {
    console.error('Setup error:', error);
    if (error.response) {
      console.error('Response data:', error.response);
    }
    process.exit(1);
  }
}

setup();

