import express from 'express';
import cors from 'cors';
import PocketBase from 'pocketbase';

const app = express();
const PORT = parseInt(process.env.APP_PUBLIC_PORT || '4173');
const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';

const pb = new PocketBase(BACKEND_URL);

app.use(cors());
app.use(express.json());

// Helper functions
function getDateString(daysAgo = 0) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

function calculateStreaks(completions, habitId) {
  if (!completions || completions.length === 0) {
    return { current_streak: 0, longest_streak: 0 };
  }

  // Filter for this habit and sort by date descending
  const habitCompletions = completions
    .filter(c => c.habit_id === habitId)
    .map(c => c.date)
    .sort((a, b) => b.localeCompare(a)); // descending

  if (habitCompletions.length === 0) {
    return { current_streak: 0, longest_streak: 0 };
  }

  const today = getDateString(0);
  let currentStreak = 0;
  let longestStreak = 0;
  let tempStreak = 0;

  // Calculate current streak (must include today)
  if (habitCompletions[0] === today) {
    let checkDate = new Date(today);
    currentStreak = 1;

    for (let i = 1; i < habitCompletions.length; i++) {
      checkDate.setDate(checkDate.getDate() - 1);
      const expectedDate = checkDate.toISOString().split('T')[0];

      if (habitCompletions[i] === expectedDate) {
        currentStreak++;
      } else {
        break;
      }
    }
  }

  // Calculate longest streak
  for (let i = 0; i < habitCompletions.length; i++) {
    if (i === 0) {
      tempStreak = 1;
    } else {
      const currentDate = new Date(habitCompletions[i]);
      const prevDate = new Date(habitCompletions[i - 1]);
      const dayDiff = (prevDate - currentDate) / (1000 * 60 * 60 * 24);

      if (dayDiff === 1) {
        tempStreak++;
      } else {
        longestStreak = Math.max(longestStreak, tempStreak);
        tempStreak = 1;
      }
    }
  }
  longestStreak = Math.max(longestStreak, tempStreak);

  return { current_streak: currentStreak, longest_streak: longestStreak };
}

// Auth middleware
const requireAuth = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authorization required' });
  }

  const token = authHeader.substring(7);
  try {
    // Verify token by setting it and checking if it's valid
    pb.authStore.save(token, null);

    // Try to get the current user to validate the token
    if (!pb.authStore.isValid) {
      throw new Error('Invalid token');
    }

    req.userId = pb.authStore.model?.id;
    if (!req.userId) {
      throw new Error('No user ID in token');
    }

    next();
  } catch (error) {
    pb.authStore.clear();
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// Health check
app.get('/api/health', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

// Auth routes
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const authData = await pb.collection('users').authWithPassword(email, password);
    res.json({ access_token: authData.token, user: authData.record });
  } catch (error) {
    console.error('Login error:', error);
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

// Habits routes
app.get('/api/habits', requireAuth, async (req, res) => {
  try {
    const habits = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.userId}" && deleted = FALSE`,
      sort: 'created'
    });

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.userId}"`
    });

    const today = getDateString(0);
    const enrichedHabits = habits.map(habit => {
      const streaks = calculateStreaks(completions, habit.id);
      const completedToday = completions.some(
        c => c.habit_id === habit.id && c.date === today
      );

      return {
        id: habit.id,
        name: habit.name,
        description: habit.description,
        color: habit.color,
        current_streak: streaks.current_streak,
        longest_streak: streaks.longest_streak,
        completed_today: completedToday,
        created: habit.created,
        updated: habit.updated
      };
    });

    res.json(enrichedHabits);
  } catch (error) {
    console.error('Get habits error:', error);
    res.status(500).json({ error: 'Failed to fetch habits' });
  }
});

app.get('/api/habits/:id', requireAuth, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.userId}" && habit_id = "${habit.id}"`
    });

    const streaks = calculateStreaks(completions, habit.id);
    const today = getDateString(0);
    const completedToday = completions.some(c => c.date === today);

    res.json({
      id: habit.id,
      name: habit.name,
      description: habit.description,
      color: habit.color,
      current_streak: streaks.current_streak,
      longest_streak: streaks.longest_streak,
      completed_today: completedToday,
      created: habit.created,
      updated: habit.updated,
      completions: completions.map(c => ({ date: c.date, id: c.id }))
    });
  } catch (error) {
    console.error('Get habit error:', error);
    if (error.status === 404) {
      return res.status(404).json({ error: 'Habit not found' });
    }
    res.status(500).json({ error: 'Failed to fetch habit' });
  }
});

app.post('/api/habits', requireAuth, async (req, res) => {
  try {
    const { name, color, description } = req.body;

    if (!name || name.length < 1 || name.length > 80) {
      return res.status(400).json({ error: 'Name must be 1-80 characters' });
    }

    if (!['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'].includes(color)) {
      return res.status(400).json({ error: 'Invalid color' });
    }

    // Check for duplicate name (case-insensitive)
    const existing = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.userId}" && deleted = FALSE`
    });

    if (existing.some(h => h.name.toLowerCase() === name.toLowerCase())) {
      return res.status(400).json({ error: 'A habit with this name already exists' });
    }

    const habit = await pb.collection('habits').create({
      user_id: req.userId,
      name,
      description: description || '',
      color,
      deleted: false
    });

    res.status(201).json({
      id: habit.id,
      name: habit.name,
      description: habit.description,
      color: habit.color,
      current_streak: 0,
      longest_streak: 0,
      completed_today: false,
      created: habit.created,
      updated: habit.updated
    });
  } catch (error) {
    console.error('Create habit error:', error);
    res.status(500).json({ error: 'Failed to create habit' });
  }
});

app.patch('/api/habits/:id', requireAuth, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    const { name, color, description } = req.body;
    const updates = {};

    if (name !== undefined) {
      if (name.length < 1 || name.length > 80) {
        return res.status(400).json({ error: 'Name must be 1-80 characters' });
      }

      // Check for duplicate name
      const existing = await pb.collection('habits').getFullList({
        filter: `user_id = "${req.userId}" && deleted = FALSE && id != "${habit.id}"`
      });

      if (existing.some(h => h.name.toLowerCase() === name.toLowerCase())) {
        return res.status(400).json({ error: 'A habit with this name already exists' });
      }

      updates.name = name;
    }

    if (color !== undefined) {
      if (!['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'].includes(color)) {
        return res.status(400).json({ error: 'Invalid color' });
      }
      updates.color = color;
    }

    if (description !== undefined) {
      if (description.length > 200) {
        return res.status(400).json({ error: 'Description must be at most 200 characters' });
      }
      updates.description = description;
    }

    const updated = await pb.collection('habits').update(req.params.id, updates);

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.userId}" && habit_id = "${updated.id}"`
    });

    const streaks = calculateStreaks(completions, updated.id);
    const today = getDateString(0);
    const completedToday = completions.some(c => c.date === today);

    res.json({
      id: updated.id,
      name: updated.name,
      description: updated.description,
      color: updated.color,
      current_streak: streaks.current_streak,
      longest_streak: streaks.longest_streak,
      completed_today: completedToday,
      created: updated.created,
      updated: updated.updated
    });
  } catch (error) {
    console.error('Update habit error:', error);
    if (error.status === 404) {
      return res.status(404).json({ error: 'Habit not found' });
    }
    res.status(500).json({ error: 'Failed to update habit' });
  }
});

app.delete('/api/habits/:id', requireAuth, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Soft delete
    await pb.collection('habits').update(req.params.id, { deleted: true });

    res.status(204).send();
