import express from 'express';
import cors from 'cors';
import PocketBase from 'pocketbase';

const app = express();
const PORT = parseInt(process.env.APP_PUBLIC_PORT || '4173');
const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';

const pb = new PocketBase(BACKEND_URL);

app.use(cors());
app.use(express.json());

// Helper functions
function getDateString(daysAgo = 0) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

function calculateStreaks(completions, habitId) {
  if (!completions || completions.length === 0) {
    return { current_streak: 0, longest_streak: 0 };
  }

  // Filter for this habit and sort by date descending
  const habitCompletions = completions
    .filter(c => c.habit_id === habitId)
    .map(c => c.date)
    .sort((a, b) => b.localeCompare(a)); // descending

  if (habitCompletions.length === 0) {
    return { current_streak: 0, longest_streak: 0 };
  }

  const today = getDateString(0);
  let currentStreak = 0;
  let longestStreak = 0;
  let tempStreak = 0;

  // Calculate current streak (must include today)
  if (habitCompletions[0] === today) {
    let checkDate = new Date(today);
    currentStreak = 1;

    for (let i = 1; i < habitCompletions.length; i++) {
      checkDate.setDate(checkDate.getDate() - 1);
      const expectedDate = checkDate.toISOString().split('T')[0];

      if (habitCompletions[i] === expectedDate) {
        currentStreak++;
      } else {
        break;
      }
    }
  }

  // Calculate longest streak
  for (let i = 0; i < habitCompletions.length; i++) {
    if (i === 0) {
      tempStreak = 1;
    } else {
      const currentDate = new Date(habitCompletions[i]);
      const prevDate = new Date(habitCompletions[i - 1]);
      const dayDiff = (prevDate - currentDate) / (1000 * 60 * 60 * 24);

      if (dayDiff === 1) {
        tempStreak++;
      } else {
        longestStreak = Math.max(longestStreak, tempStreak);
        tempStreak = 1;
      }
    }
  }
  longestStreak = Math.max(longestStreak, tempStreak);

  return { current_streak: currentStreak, longest_streak: longestStreak };
}

// Auth middleware
const requireAuth = async (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authorization required' });
  }

  const token = authHeader.substring(7);
  try {
    // Verify token by setting it and checking if it's valid
    pb.authStore.save(token, null);

    // Try to get the current user to validate the token
    if (!pb.authStore.isValid) {
      throw new Error('Invalid token');
    }

    req.userId = pb.authStore.model?.id;
    if (!req.userId) {
      throw new Error('No user ID in token');
    }

    next();
  } catch (error) {
    pb.authStore.clear();
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

