import PocketBase from 'pocketbase';

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

function getDateString(daysAgo = 0) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

async function seedUser() {
  console.log('\n=== Seeding User ===');
  try {
    // Try to authenticate with the demo user
    try {
      await pb.collection('users').authWithPassword('demo@ethara.ai', 'deku-demo-pw-2026');
      console.log('✓ Demo user already exists and can authenticate');
      return pb.authStore.model;
    } catch (e) {
      // User doesn't exist or wrong password, create it
      console.log('Creating demo user...');
      const user = await pb.collection('users').create({
        email: 'demo@ethara.ai',
        password: 'deku-demo-pw-2026',
        passwordConfirm: 'deku-demo-pw-2026',
        emailVisibility: true
      });
      console.log('✓ Demo user created');
      return user;
    }
  } catch (error) {
    console.error('Error seeding user:', error.message);
    throw error;
  }
}

async function seedHabits(userId) {
  console.log('\n=== Seeding Habits ===');
  const habitData = [
    { name: 'Meditate', color: 'indigo', description: '' },
    { name: 'Read 20 minutes', color: 'teal', description: '' },
    { name: 'No soda', color: 'amber', description: '' }
  ];

  const habits = [];
  for (const data of habitData) {
    try {
      // Check if habit already exists
      const existing = await pb.collection('habits').getFullList({
        filter: `user_id = "${userId}" && name = "${data.name}"`
      });

      if (existing.length > 0 && !existing[0].deleted) {
        console.log(`✓ Habit "${data.name}" already exists`);
        habits.push(existing[0]);
