#!/usr/bin/env node
/**
 * Complete PocketBase setup script
 * This script creates collections and seeds data
 */

import PocketBase from 'pocketbase';
import { execSync } from 'child_process';

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

function getDateString(daysAgo = 0) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

async function createCollections() {
  console.log('\n=== Creating Collections ===');

  // This requires admin authentication
  // For now, we'll use curl to create collections via the API
  // This assumes admin has been set up

  try {
    // Try to get collections to see if admin is authenticated
    const collections = await pb.collections.getFullList();
    console.log(`✓ Found ${collections.length} existing collections`);

    // Check for our required collections
    const hasHabits = collections.some(c => c.name === 'habits');
    const hasCompletions = collections.some(c => c.name === 'completions');

    return { hasHabits, hasCompletions };
  } catch (error) {
    console.log('⚠️  Cannot access collections API (requires admin)');
    return { hasHabits: false, hasCompletions: false };
  }
}

async function testCollections() {
  console.log('\n=== Testing Collection Access ===');

  try {
    // Try to list habits (will fail if collection doesn't exist)
    const habits = await pb.collection('habits').getList(1, 1);
    console.log('✓ habits collection is accessible');
  } catch (error) {
    if (error.status === 404) {
      console.log('✗ habits collection does not exist');
      return false;
    } else if (error.status === 403 || error.status === 401) {
      console.log('✓ habits collection exists (auth required for access)');
    }
  }

  try {
    const completions = await pb.collection('completions').getList(1, 1);
    console.log('✓ completions collection is accessible');
  } catch (error) {
    if (error.status === 404) {
      console.log('✗ completions collection does not exist');
      return false;
    } else if (error.status === 403 || error.status === 401) {
      console.log('✓ completions collection exists (auth required for access)');
    }
  }

  return true;
}

async function seedData() {
  console.log('\n=== Seeding Data ===');

  // Create or authenticate demo user
  let user;
  try {
    const authData = await pb.collection('users').authWithPassword(
      'demo@ethara.ai',
      'deku-demo-pw-2026'
    );
    user = authData.record;
    console.log('✓ Demo user authenticated');
  } catch (error) {
    try {
      user = await pb.collection('users').create({
        email: 'demo@ethara.ai',
        password: 'deku-demo-pw-2026',
        passwordConfirm: 'deku-demo-pw-2026',
        emailVisibility: true
      });
      console.log('✓ Demo user created');

      // Authenticate as the new user
      await pb.collection('users').authWithPassword(
        'demo@ethara.ai',
        'deku-demo-pw-2026'
      );
    } catch (createError) {
      console.error('✗ Failed to create demo user:', createError.message);
      throw createError;
    }
  }

  // Create habits
  const habitData = [
    { name: 'Meditate', color: 'indigo', description: '' },
    { name: 'Read 20 minutes', color: 'teal', description: '' },
    { name: 'No soda', color: 'amber', description: '' }
  ];

  const habits = [];
  for (const data of habitData) {
    try {
      const existing = await pb.collection('habits').getFullList({
        filter: `user_id = "${user.id}" && name = "${data.name}" && deleted = FALSE`
      });

      if (existing.length > 0) {
        habits.push(existing[0]);
        console.log(`✓ Habit "${data.name}" already exists`);
      } else {
        const habit = await pb.collection('habits').create({
          user_id: user.id,
          ...data,
          deleted: false
        });
        habits.push(habit);
        console.log(`✓ Created habit: ${data.name}`);
      }
    } catch (error) {
      console.error(`✗ Error with habit "${data.name}":`, error.message);
      throw error;
    }
  }

  // Create completions
