  // Meditate: 5-day streak
  for (let i = 0; i < 5; i++) {
    const date = getDateString(i);
    try {
      const existing = await pb.collection('completions').getFullList({
        filter: `user_id = "${user.id}" && habit_id = "${habits[0].id}" && date = "${date}"`
      });

      if (existing.length === 0) {
        await pb.collection('completions').create({
          user_id: user.id,
          habit_id: habits[0].id,
          date: date
        });
      }
    } catch (error) {
      // Ignore duplicate errors
      if (!error.message.includes('UNIQUE')) {
        console.error(`Warning: Could not create completion for ${date}:`, error.message);
      }
    }
  }
  console.log('✓ Seeded completions for Meditate');

  // Read 20 minutes: 3-day streak 7-9 days ago
  for (let i = 7; i <= 9; i++) {
    const date = getDateString(i);
    try {
      const existing = await pb.collection('completions').getFullList({
        filter: `user_id = "${user.id}" && habit_id = "${habits[1].id}" && date = "${date}"`
      });

      if (existing.length === 0) {
        await pb.collection('completions').create({
          user_id: user.id,
          habit_id: habits[1].id,
          date: date
        });
      }
    } catch (error) {
      if (!error.message.includes('UNIQUE')) {
        console.error(`Warning: Could not create completion for ${date}:`, error.message);
      }
    }
  }
  console.log('✓ Seeded completions for Read 20 minutes');

  // No soda: only today
  try {
    const existing = await pb.collection('completions').getFullList({
      filter: `user_id = "${user.id}" && habit_id = "${habits[2].id}" && date = "${today}"`
    });

    if (existing.length === 0) {
      await pb.collection('completions').create({
        user_id: user.id,
        habit_id: habits[2].id,
        date: today
      });
    }
  } catch (error) {
    if (!error.message.includes('UNIQUE')) {
      console.error(`Warning: Could not create completion for today:`, error.message);
    }
  }
  console.log('✓ Seeded completions for No soda');
}

