#!/usr/bin/env node
import PocketBase from 'pocketbase';

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = process.env.PB_ADMIN_EMAIL || 'admin@ethara.local';
const ADMIN_PASSWORD = process.env.PB_ADMIN_PASSWORD || 'admin-ethara-2026-secure';

const pb = new PocketBase(BACKEND_URL);

async function updateCollectionRules() {
  console.log('Attempting to update PocketBase collection rules...\n');

  try {
    // Try to authenticate as admin
    await pb.admins.authWithPassword(ADMIN_EMAIL, ADMIN_PASSWORD);
    console.log('✓ Authenticated as admin\n');

    // Update habits collection rules
    try {
      const habitsCollection = await pb.collections.getOne('habits');

      await pb.collections.update(habitsCollection.id, {
        listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = FALSE',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
      });

      console.log('✓ Updated habits collection rules');
    } catch (error) {
      console.error('✗ Failed to update habits collection:', error.message);
    }

