// API client with typed fetch wrapper

const API_BASE = '/api';

class APIError extends Error {
  constructor(
    message: string,
    public status: number,
    public data?: any
  ) {
    super(message);
    this.name = 'APIError';
  }
}

async function fetchJSON<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem('auth_token');

  const headers: HeadersInit = {
    'Content-Type': 'application/json',
    ...options.headers,
  };

  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers,
  });

  if (response.status === 401) {
    // Token expired or invalid
    localStorage.removeItem('auth_token');
    localStorage.removeItem('user_email');
    window.location.href = '/login?session=expired';
    throw new APIError('Session expired', 401);
  }

  if (!response.ok) {
    let errorData;
    try {
      errorData = await response.json();
    } catch {
      errorData = { error: response.statusText };
    }
    throw new APIError(
      errorData.error || errorData.message || 'Request failed',
      response.status,
      errorData
    );
  }

  if (response.status === 204) {
    return null as T;
  }

  return response.json();
}

export const api = {
  // Auth
  login: async (email: string, password: string) => {
    const data = await fetchJSON<{ access_token: string; user?: any }>(
      '/auth/login',
      {
        method: 'POST',
        body: JSON.stringify({ email, password }),
      }
    );
    localStorage.setItem('auth_token', data.access_token);
    if (data.user?.email) {
      localStorage.setItem('user_email', data.user.email);
    }
    return data;
  },

  logout: () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('user_email');
  },

  // Habits
  getHabits: () =>
    fetchJSON<
      Array<{
        id: string;
        name: string;
        description?: string;
        color: string;
        current_streak: number;
        longest_streak: number;
        completed_today: boolean;
        created: string;
        updated: string;
      }>
    >('/habits'),

  getHabit: (id: string) =>
    fetchJSON<{
      id: string;
      name: string;
      description?: string;
      color: string;
      current_streak: number;
      longest_streak: number;
      completed_today: boolean;
      completions: Array<{ id: string; date: string }>;
      created: string;
      updated: string;
    }>(`/habits/${id}`),

  createHabit: (data: {
    name: string;
    color: string;
    description?: string;
  }) =>
    fetchJSON<any>('/habits', {
      method: 'POST',
      body: JSON.stringify(data),
    }),

  updateHabit: (
    id: string,
    data: { name?: string; color?: string; description?: string }
  ) =>
    fetchJSON<any>(`/habits/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    }),

  deleteHabit: (id: string) =>
    fetchJSON<void>(`/habits/${id}`, {
      method: 'DELETE',
    }),

  // Completions
  markComplete: (habitId: string, date: string) =>
    fetchJSON<any>(`/habits/${habitId}/complete`, {
      method: 'POST',
      body: JSON.stringify({ date }),
    }),

  markIncomplete: (habitId: string, date: string) =>
    fetchJSON<void>(`/habits/${habitId}/complete`, {
      method: 'DELETE',
      body: JSON.stringify({ date }),
    }),

  // Dashboard
  getDashboard: () =>
    fetchJSON<{
      total_habits: number;
      total_completions: number;
      habits_with_active_streak: number;
      habits: Array<{
        id: string;
        name: string;
        color: string;
        current_streak: number;
        longest_streak: number;
        completed_today: boolean;
      }>;
    }>('/dashboard'),
};

export { APIError };

