    return data;
  },

  logout: () => {
    localStorage.removeItem('auth_token');
    localStorage.removeItem('user_email');
  },

  // Habits
  getHabits: () =>
    fetchJSON<
      Array<{
        id: string;
        name: string;
        description?: string;
        color: string;
        current_streak: number;
        longest_streak: number;
        completed_today: boolean;
        created: string;
        updated: string;
      }>
    >('/habits'),

  getHabit: (id: string) =>
    fetchJSON<{
      id: string;
      name: string;
      description?: string;
      color: string;
      current_streak: number;
      longest_streak: number;
      completed_today: boolean;
      completions: Array<{ id: string; date: string }>;
      created: string;
      updated: string;
    }>(`/habits/${id}`),

  createHabit: (data: {
    name: string;
    color: string;
    description?: string;
  }) =>
    fetchJSON<any>('/habits', {
      method: 'POST',
      body: JSON.stringify(data),
    }),

  updateHabit: (
    id: string,
    data: { name?: string; color?: string; description?: string }
  ) =>
    fetchJSON<any>(`/habits/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    }),

  deleteHabit: (id: string) =>
    fetchJSON<void>(`/habits/${id}`, {
      method: 'DELETE',
    }),

  // Completions
  markComplete: (habitId: string, date: string) =>
    fetchJSON<any>(`/habits/${habitId}/complete`, {
      method: 'POST',
      body: JSON.stringify({ date }),
    }),

  markIncomplete: (habitId: string, date: string) =>
    fetchJSON<void>(`/habits/${habitId}/complete`, {
      method: 'DELETE',
      body: JSON.stringify({ date }),
    }),

  // Dashboard
  getDashboard: () =>
    fetchJSON<{
      total_habits: number;
      total_completions: number;
      habits_with_active_streak: number;
      habits: Array<{
        id: string;
        name: string;
        color: string;
        current_streak: number;
        longest_streak: number;
        completed_today: boolean;
      }>;
    }>('/dashboard'),
};

export { APIError };

