import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';
import { useState } from 'react';

const HABIT_COLORS: Record<string, string> = {
  indigo: '#4F46E5',
  teal: '#0D9488',
  amber: '#D97706',
  rose: '#E11D48',
  slate: '#475569',
  forest: '#166534',
};

export default function Dashboard() {
  const queryClient = useQueryClient();
  const [error, setError] = useState('');

  const { data: dashboard, isLoading } = useQuery({
    queryKey: ['dashboard'],
    queryFn: api.getDashboard,
  });

  const toggleCompleteMutation = useMutation({
    mutationFn: async ({
      habitId,
      date,
      completed,
    }: {
      habitId: string;
      date: string;
      completed: boolean;
    }) => {
      if (completed) {
        await api.markIncomplete(habitId, date);
      } else {
        await api.markComplete(habitId, date);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      setError('');
    },
    onError: (err: any) => {
      setError(err.message);
    },
  });

  const handleToggleToday = (habitId: string, completed: boolean) => {
    const today = new Date().toISOString().split('T')[0];
    toggleCompleteMutation.mutate({ habitId, date: today, completed });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-text">Loading...</div>
      </div>
    );
  }

  if (!dashboard) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-text">Failed to load dashboard</div>
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-[28px] font-medium text-primary-text mb-1">
          Dashboard
        </h1>
        <p className="text-muted-text">Track your daily habits</p>
      </div>

      {error && (
        <div className="p-3 rounded bg-danger/10 border border-danger/20 text-sm text-danger">
          {error}
        </div>
      )}

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-surface rounded-card border border-border p-6">
          <div className="text-sm text-muted-text mb-1">Total Habits</div>
          <div className="text-[28px] font-mono font-medium text-primary-text">
            {dashboard.total_habits}
          </div>
        </div>
        <div className="bg-surface rounded-card border border-border p-6">
          <div className="text-sm text-muted-text mb-1">Active Streaks</div>
          <div className="text-[28px] font-mono font-medium text-primary-text">
            {dashboard.habits_with_active_streak}
          </div>
        </div>
        <div className="bg-surface rounded-card border border-border p-6">
          <div className="text-sm text-muted-text mb-1">Total Completions</div>
          <div className="text-[28px] font-mono font-medium text-primary-text">
            {dashboard.total_completions}
          </div>
        </div>
      </div>

      {/* Habits List */}
      <div className="bg-surface rounded-card border border-border overflow-hidden">
        <div className="px-6 py-4 border-b border-border">
          <h2 className="text-lg font-medium text-primary-text">Your Habits</h2>
        </div>

        {dashboard.habits.length === 0 ? (
          <div className="px-6 py-12 text-center">
            <p className="text-muted-text mb-4">No habits yet</p>
            <a
              href="/habits"
              className="inline-block px-4 py-2 bg-primary hover:bg-primary-hover text-white
                       rounded transition-colors"
            >
              Add your first habit
            </a>
          </div>
        ) : (
          <div className="divide-y divide-border">
            {dashboard.habits.map((habit) => (
              <div
                key={habit.id}
                className="px-6 py-4 flex items-center justify-between hover:bg-background/50 transition-colors"
              >
                <div className="flex items-center space-x-4 flex-1">
                  <div
                    className="w-3 h-3 rounded-full flex-shrink-0"
                    style={{ backgroundColor: HABIT_COLORS[habit.color] }}
                  />
                  <div className="flex-1 min-w-0">
                    <div className="font-medium text-primary-text truncate">
                      {habit.name}
                    </div>
                  </div>
                </div>

                <div className="flex items-center space-x-6">
                  <div className="text-center hidden sm:block">
                    <div className="text-xs text-muted-text">Current</div>
                    <div className="text-sm font-mono font-medium text-primary-text">
                      {habit.current_streak}
                    </div>
                  </div>
                  <div className="text-center hidden sm:block">
                    <div className="text-xs text-muted-text">Longest</div>
                    <div className="text-sm font-mono font-medium text-primary-text">
                      {habit.longest_streak}
                    </div>
                  </div>
                  <button
                    onClick={() =>
                      handleToggleToday(habit.id, habit.completed_today)
                    }
                    disabled={toggleCompleteMutation.isPending}
                    className={`w-11 h-11 rounded border-2 transition-all flex items-center justify-center
                              ${
                                habit.completed_today
                                  ? 'border-success bg-success text-white'
                                  : 'border-border hover:border-success'
                              }
                              disabled:opacity-50 disabled:cursor-not-allowed`}
                    aria-label={
                      habit.completed_today
                        ? 'Mark as incomplete'
                        : 'Mark as complete'
                    }
                  >
                    {habit.completed_today && (
                      <svg
                        className="w-5 h-5"
                        fill="none"
                        stroke="currentColor"
                        viewBox="0 0 24 24"
                      >
                        <path
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          strokeWidth={2}
                          d="M5 13l4 4L19 7"
                        />
                      </svg>
                    )}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

