import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';
import { useState } from 'react';
import { Link } from 'react-router-dom';

const HABIT_COLORS = [
  { value: 'indigo', label: 'Indigo', color: '#4F46E5' },
  { value: 'teal', label: 'Teal', color: '#0D9488' },
  { value: 'amber', label: 'Amber', color: '#D97706' },
  { value: 'rose', label: 'Rose', color: '#E11D48' },
  { value: 'slate', label: 'Slate', color: '#475569' },
  { value: 'forest', label: 'Forest', color: '#166534' },
];

export default function Habits() {
  const queryClient = useQueryClient();
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedHabit, setSelectedHabit] = useState<any>(null);
  const [error, setError] = useState('');

  const [formData, setFormData] = useState({
    name: '',
    color: 'indigo',
    description: '',
  });

  const { data: habits, isLoading } = useQuery({
    queryKey: ['habits'],
    queryFn: api.getHabits,
  });

  const createMutation = useMutation({
    mutationFn: api.createHabit,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      setShowAddModal(false);
      setFormData({ name: '', color: 'indigo', description: '' });
      setError('');
    },
    onError: (err: any) => setError(err.message),
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: any }) =>
      api.updateHabit(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      setShowEditModal(false);
      setSelectedHabit(null);
      setError('');
    },
    onError: (err: any) => setError(err.message),
  });

  const deleteMutation = useMutation({
    mutationFn: api.deleteHabit,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      setShowDeleteModal(false);
      setSelectedHabit(null);
      setError('');
    },
    onError: (err: any) => setError(err.message),
  });

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    createMutation.mutate(formData);
  };

  const handleEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedHabit) {
      updateMutation.mutate({ id: selectedHabit.id, data: formData });
    }
  };

  const handleDelete = () => {
    if (selectedHabit) {
      deleteMutation.mutate(selectedHabit.id);
    }
  };

  const openEditModal = (habit: any) => {
    setSelectedHabit(habit);
    setFormData({
      name: habit.name,
      color: habit.color,
      description: habit.description || '',
    });
    setShowEditModal(true);
    setError('');
  };

  const openDeleteModal = (habit: any) => {
    setSelectedHabit(habit);
    setShowDeleteModal(true);
    setError('');
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-text">Loading...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-[28px] font-medium text-primary-text mb-1">
            Habits
          </h1>
          <p className="text-muted-text">Manage your daily habits</p>
        </div>
        <button
          onClick={() => {
            setFormData({ name: '', color: 'indigo', description: '' });
            setShowAddModal(true);
            setError('');
          }}
          className="h-11 px-6 bg-primary hover:bg-primary-hover text-white font-medium rounded
                   transition-colors"
        >
          Add Habit
        </button>
      </div>

      {error && (
        <div className="p-3 rounded bg-danger/10 border border-danger/20 text-sm text-danger">
          {error}
        </div>
      )}

      {!habits || habits.length === 0 ? (
        <div className="bg-surface rounded-card border border-border p-12 text-center">
          <p className="text-muted-text mb-4">No habits yet</p>
          <button
            onClick={() => setShowAddModal(true)}
            className="inline-block px-4 py-2 bg-primary hover:bg-primary-hover text-white
                     rounded transition-colors"
          >
            Add your first habit
          </button>
        </div>
      ) : (
        <div className="bg-surface rounded-card border border-border overflow-hidden">
          <table className="w-full">
            <thead className="bg-background/50 border-b border-border sticky top-0">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider">
                  Habit
                </th>
