                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider hidden sm:table-cell">
                  Current Streak
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider hidden sm:table-cell">
                  Longest Streak
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-muted-text uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {habits.map((habit) => (
