        <div className="bg-surface rounded-card border border-border overflow-hidden">
          <table className="w-full">
            <thead className="bg-background/50 border-b border-border sticky top-0">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider">
                  Habit
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider hidden sm:table-cell">
                  Current Streak
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-muted-text uppercase tracking-wider hidden sm:table-cell">
                  Longest Streak
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-muted-text uppercase tracking-wider">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {habits.map((habit) => (
                <tr key={habit.id} className="hover:bg-background/30 transition-colors">
                  <td className="px-6 py-4">
                    <Link
                      to={`/habits/${habit.id}`}
                      className="flex items-center space-x-3 hover:text-primary transition-colors"
                    >
                      <div
                        className="w-3 h-3 rounded-full flex-shrink-0"
                        style={{
                          backgroundColor:
                            HABIT_COLORS.find((c) => c.value === habit.color)
                              ?.color || '#4F46E5',
                        }}
                      />
                      <div>
                        <div className="font-medium text-primary-text">
                          {habit.name}
                        </div>
                        {habit.description && (
                          <div className="text-sm text-muted-text">
                            {habit.description}
                          </div>
                        )}
                      </div>
                    </Link>
                  </td>
                  <td className="px-6 py-4 hidden sm:table-cell">
                    <span className="font-mono text-primary-text">
                      {habit.current_streak}
                    </span>
                  </td>
                  <td className="px-6 py-4 hidden sm:table-cell">
                    <span className="font-mono text-primary-text">
                      {habit.longest_streak}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right space-x-2">
                    <button
                      onClick={() => openEditModal(habit)}
                      className="text-sm text-primary hover:text-primary-hover transition-colors"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => openDeleteModal(habit)}
                      className="text-sm text-danger hover:text-danger/80 transition-colors"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Add Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-surface rounded-card border border-border p-6 w-full max-w-md">
