              </div>

              <div>
                <label className="block text-sm font-medium text-primary-text mb-1">
                  Color
                </label>
                <div className="grid grid-cols-3 gap-2">
                  {HABIT_COLORS.map((color) => (
                    <button
                      key={color.value}
                      type="button"
                      onClick={() =>
                        setFormData({ ...formData, color: color.value })
                      }
                      className={`flex items-center space-x-2 px-3 py-2 border rounded transition-all
                                ${
                                  formData.color === color.value
                                    ? 'border-primary bg-primary/10'
                                    : 'border-border hover:border-primary/50'
                                }`}
                    >
                      <div
                        className="w-4 h-4 rounded-full"
                        style={{ backgroundColor: color.color }}
                      />
                      <span className="text-sm text-primary-text">
                        {color.label}
                      </span>
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-primary-text mb-1">
                  Description (optional)
                </label>
                <textarea
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  maxLength={200}
                  rows={3}
                  className="w-full px-3 py-2 border border-border rounded bg-background text-primary-text
                           focus:outline-none focus:ring-2 focus:ring-primary resize-none"
                />
              </div>

              <div className="flex space-x-3 pt-2">
                <button
                  type="submit"
                  disabled={updateMutation.isPending}
                  className="flex-1 h-11 bg-primary hover:bg-primary-hover text-white font-medium rounded
                           transition-colors disabled:opacity-50"
                >
                  {updateMutation.isPending ? 'Saving...' : 'Save Changes'}
                </button>
                <button
                  type="button"
                  onClick={() => setShowEditModal(false)}
                  className="h-11 px-6 border border-border hover:bg-background/50 text-primary-text
                           rounded transition-colors"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal && selectedHabit && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-surface rounded-card border border-border p-6 w-full max-w-md">
            <h2 className="text-lg font-medium text-primary-text mb-4">
              Delete Habit
            </h2>
            <p className="text-muted-text mb-6">
              Are you sure you want to delete "{selectedHabit.name}"? This will
              hide the habit but preserve its completion history.
            </p>
            <div className="flex space-x-3">
              <button
                onClick={handleDelete}
                disabled={deleteMutation.isPending}
                className="flex-1 h-11 bg-danger hover:bg-danger/90 text-white font-medium rounded
                         transition-colors disabled:opacity-50"
              >
                {deleteMutation.isPending ? 'Deleting...' : 'Delete'}
              </button>
              <button
                onClick={() => setShowDeleteModal(false)}
                className="h-11 px-6 border border-border hover:bg-background/50 text-primary-text
                         rounded transition-colors"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
