import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useParams, Link } from 'react-router-dom';
import { api } from '../lib/api';
import { useState } from 'react';

const HABIT_COLORS: Record<string, string> = {
  indigo: '#4F46E5',
  teal: '#0D9488',
  amber: '#D97706',
  rose: '#E11D48',
  slate: '#475569',
  forest: '#166534',
};

function getLastNDays(n: number) {
  const days = [];
  const today = new Date();

  for (let i = n - 1; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i);
    days.push(date.toISOString().split('T')[0]);
  }

  return days;
}

export default function HabitDetail() {
  const { id } = useParams<{ id: string }>();
  const queryClient = useQueryClient();
  const [error, setError] = useState('');

  const { data: habit, isLoading } = useQuery({
    queryKey: ['habit', id],
    queryFn: () => api.getHabit(id!),
    enabled: !!id,
  });

  const toggleCompleteMutation = useMutation({
    mutationFn: async ({
      date,
      completed,
    }: {
      date: string;
      completed: boolean;
    }) => {
      if (completed) {
        await api.markIncomplete(id!, date);
      } else {
        await api.markComplete(id!, date);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habit', id] });
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      setError('');
    },
    onError: (err: any) => {
      setError(err.message);
    },
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-text">Loading...</div>
      </div>
    );
  }

  if (!habit) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-muted-text">Habit not found</div>
      </div>
    );
  }

  const completionDates = new Set(habit.completions.map((c) => c.date));
  const last90Days = getLastNDays(90);

  const handleToggle = (date: string) => {
    const completed = completionDates.has(date);
    toggleCompleteMutation.mutate({ date, completed });
  };

  return (
    <div className="space-y-6">
      <div>
        <Link
          to="/habits"
          className="inline-flex items-center text-sm text-muted-text hover:text-primary-text mb-4"
        >
          <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
          </svg>
          Back to Habits
        </Link>

        <div className="flex items-center space-x-4">
          <div
            className="w-4 h-4 rounded-full flex-shrink-0"
            style={{ backgroundColor: HABIT_COLORS[habit.color] }}
          />
          <div>
            <h1 className="text-[28px] font-medium text-primary-text">
              {habit.name}
            </h1>
            {habit.description && (
              <p className="text-muted-text mt-1">{habit.description}</p>
            )}
          </div>
        </div>
      </div>

      {error && (
        <div className="p-3 rounded bg-danger/10 border border-danger/20 text-sm text-danger">
          {error}
        </div>
      )}

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-surface rounded-card border border-border p-4">
          <div className="text-xs text-muted-text mb-1">Current Streak</div>
          <div className="text-[22px] font-mono font-medium text-primary-text">
            {habit.current_streak}
          </div>
        </div>
        <div className="bg-surface rounded-card border border-border p-4">
          <div className="text-xs text-muted-text mb-1">Longest Streak</div>
          <div className="text-[22px] font-mono font-medium text-primary-text">
            {habit.longest_streak}
          </div>
        </div>
        <div className="bg-surface rounded-card border border-border p-4">
          <div className="text-xs text-muted-text mb-1">Completions</div>
          <div className="text-[22px] font-mono font-medium text-primary-text">
            {habit.completions.length}
          </div>
        </div>
        <div className="bg-surface rounded-card border border-border p-4">
          <div className="text-xs text-muted-text mb-1">Status</div>
          <div className="text-sm font-medium">
            {habit.completed_today ? (
              <span className="text-success">Completed Today</span>
            ) : (
              <span className="text-muted-text">Not Yet</span>
            )}
          </div>
        </div>
      </div>

      {/* Calendar */}
      <div className="bg-surface rounded-card border border-border p-6">
        <h2 className="text-lg font-medium text-primary-text mb-4">
          Last 90 Days
        </h2>

        <div className="grid grid-cols-7 gap-2">
          {last90Days.map((date) => {
            const isCompleted = completionDates.has(date);
            const isToday = date === new Date().toISOString().split('T')[0];
            const dateObj = new Date(date + 'T00:00:00');
            const dayOfMonth = dateObj.getDate();

            return (
              <button
                key={date}
                onClick={() => handleToggle(date)}
                disabled={toggleCompleteMutation.isPending}
                className={`aspect-square rounded border-2 transition-all flex items-center justify-center
                          text-xs font-medium relative group
                          ${
                            isCompleted
                              ? 'border-transparent'
                              : 'border-border hover:border-primary/50'
                          }
                          ${isToday ? 'ring-2 ring-primary ring-offset-2' : ''}
                          disabled:opacity-50 disabled:cursor-not-allowed`}
                style={{
                  backgroundColor: isCompleted
                    ? HABIT_COLORS[habit.color]
                    : 'transparent',
                  color: isCompleted ? '#fff' : undefined,
                }}
                title={`${date}${isCompleted ? ' - Completed' : ''}`}
              >
                <span className={isCompleted ? 'text-white' : 'text-muted-text'}>
                  {dayOfMonth}
                </span>

                {/* Tooltip */}
                <div className="absolute bottom-full left-1/2 transform -translate-x-1/2 mb-2
                              bg-primary-text text-surface text-xs rounded px-2 py-1
                              opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none
                              whitespace-nowrap z-10">
                  {date}
                  {isCompleted && ' ✓'}
                </div>
              </button>
            );
          })}
        </div>

        <div className="mt-4 flex items-center justify-center space-x-4 text-xs text-muted-text">
          <div className="flex items-center space-x-2">
            <div className="w-4 h-4 border-2 border-border rounded" />
            <span>Incomplete</span>
          </div>
          <div className="flex items-center space-x-2">
            <div
              className="w-4 h-4 rounded"
              style={{ backgroundColor: HABIT_COLORS[habit.color] }}
            />
            <span>Completed</span>
          </div>
        </div>
      </div>
    </div>
  );
}

